from __future__ import annotations

import base64, gzip, hashlib, re
from pathlib import Path

TEMPLATE_SHA256 = '77b796c3fc67d4ff599e89f67e82e910f9f2e0faded3d1422627aacf65c0274b'
TEMPLATE_PAYLOAD = ''

def read(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")

def write(path: str, text: str) -> None:
    Path(path).write_text(text, encoding="utf-8")

def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    if new in text:
        return
    if old not in text:
        raise RuntimeError(f"Expected nine-step restore fragment not found in {path}: {old[:100]!r}")
    write(path, text.replace(old, new, 1))

template_bytes = gzip.decompress(base64.b64decode(TEMPLATE_PAYLOAD))
actual_sha = hashlib.sha256(template_bytes).hexdigest()
if actual_sha != TEMPLATE_SHA256:
    raise RuntimeError(f"Nine-step wizard payload integrity failed: {actual_sha}")
Path("templates/erp/project_wizard.html").write_bytes(template_bytes)

replace_once('erp/views.py', 'Projekt {project.number} über den 3-Schritte-Assistenten angelegt.', 'Projekt {project.number} über den 9-Schritte-Assistenten angelegt.')
