replace_once('tests/test_workflow_release.py', '        self.assertContains(wizard, "3-Schritte-Projektassistent")\n        self.assertNotContains(wizard, "9-Schritte-Projektassistent")\n        self.assertEqual(wizard.content.decode().count(\'data-step="\'), 3)', '        self.assertContains(wizard, "9-Schritte-Projektassistent")\n        self.assertNotContains(wizard, "10-Schritte-Projektassistent")\n        self.assertEqual(wizard.content.decode().count(\'data-step="\'), 9)')
